import type { AnalysisCtx, Severity } from "./types.js";
import type { Dataset, SectionId } from "./sections.js";
import type { ProviderId } from "./provider.js";

export type Rows = Record<string, any>[];
export interface Hit { severity: Severity; title: string; why: string; fix: string; /** Ready-to-review SQL. If omitted, the finding's evidence may still produce some (see fixes.ts). */ sql?: string; evidence?: unknown }
export interface Pass { note: string }

export interface X {
  ctx: AnalysisCtx;
  d: Record<string, Dataset>;
  rows: (id: string) => Rows;
  /** Looks a setting up across every settings dataset. */
  setting: (name: string) => string | undefined;
}

export interface CheckDef {
  id: string; section: SectionId; title: string;
  /** What it looks for / when it flags, in plain words (drives the docs and the "what we checked" list). */
  looks: string; flags: string;
  /** Datasets this check reads. If one failed or is unavailable, the check is skipped with the reason. */
  uses?: string[];
  /** Only meaningful when you run the server yourself (managed providers handle it). */
  selfHosted?: boolean;
  /** Only for these providers. */
  providers?: ProviderId[];
  run: (x: X) => Promise<Hit | Pass | null> | Hit | Pass | null;
}

export const pl = (n: number, one: string, many: string) => (n === 1 ? one : many);
export const top = <T,>(rows: T[], n = 10) => rows.slice(0, n);
export const GB = 1024 ** 3, MB = 1024 ** 2;
