// Turns a collected bundle into findings. Needs no connection, so the same analysis runs on a hosted scan and on a
// bundle someone collected on their own machine and uploaded.
import type { AnalysisCtx, Finding, ScanOptions } from "./types.js";
import type { CheckResult, Dataset, Vital } from "./sections.js";
import type { Bundle, RoleInfo } from "./bundle.js";
import { CATEGORY } from "./sections.js";
import { profileFor } from "./provider.js";
import { ALL_DEFS, vitalsFrom } from "./inspect.js";
import { CHECKS_A } from "./checks_a.js";
import { CHECKS_B } from "./checks_b.js";
import { CHECKS_C } from "./checks_c.js";
import { CHECKS_D } from "./checks_d.js";
import type { CheckDef, X } from "./checkdef.js";
import { fixSql } from "./fixes.js";
import { triage } from "./triage.js";

/** The full registry: every check the product runs, in display order. */
export const CHECKS: CheckDef[] = [...CHECKS_A, ...CHECKS_B, ...CHECKS_C, ...CHECKS_D];

/** How the scan actually connected, so the report can describe its own access truthfully. Older reports carry only the first five fields. */
export type SessionInfo = { role: string; superuser: boolean; monitor: boolean; tls: boolean; readOnly: true } & Partial<RoleInfo>;
export interface RunResult { findings: Finding[]; checks: CheckResult[]; skipped: { check: string; reason: string }[]; serverVersion: string; provider: string; datasets: Dataset[]; vitals: Vital[]; session: SessionInfo }

async function evaluate(def: CheckDef, ctx: AnalysisCtx, byId: Record<string, Dataset>): Promise<{ result: CheckResult; finding?: Finding }> {
  const base = { id: def.id, section: def.section, title: def.title, looks: def.looks, flags: def.flags };
  const na = (reason: string) => ({ result: { ...base, status: "na" as const, reason } });
  const skip = (reason: string) => ({ result: { ...base, status: "skipped" as const, reason } });
  if (def.selfHosted && ctx.profile.id !== "generic") return na(`Handled by your provider (${ctx.profile.id}).`);
  if (def.providers && !def.providers.includes(ctx.profile.id)) return na(`Only applies to ${def.providers.join(", ")}.`);
  for (const u of def.uses ?? []) {
    const d = byId[u];
    if (!d) return na("Not available on this server version or provider.");
    if (d.error) return skip(`Couldn't read ${d.title.toLowerCase()}: ${d.error}`);
    if (d.note) return skip(d.note);
  }
  const rows = (id: string) => byId[id]?.rows ?? [];
  const x: X = { ctx, d: byId, rows, setting: (name) => { for (const d of Object.values(byId)) for (const r of d.rows) if (r.name === name && "setting" in r) return String(r.setting); } };
  try {
    const out = await def.run(x);
    if (out && "severity" in out) {
      const finding: Finding = { id: def.id, section: def.section, category: CATEGORY[def.section], severity: out.severity, title: out.title, why: out.why, fix: out.fix, sql: out.sql ?? fixSql(def.id, out.evidence), evidence: out.evidence as Finding["evidence"] };
      return { result: { ...base, status: "flagged", severity: out.severity }, finding };
    }
    return { result: { ...base, status: "passed", reason: out?.note } };
  } catch (e: any) {
    return skip(String(e.message ?? e));
  }
}

/** Datasets with their titles, descriptions and columns from this registry, and rows from the bundle. */
export function datasetsFrom(bundle: Bundle): Dataset[] {
  const got = new Map(bundle.datasets.map((d) => [d.id, d]));
  const out: Dataset[] = [];
  for (const def of ALL_DEFS) {
    const d = got.get(def.id);
    if (!d) continue;
    out.push({ id: def.id, section: def.section, title: def.title, description: def.description, source: def.source, layout: def.layout ?? "table", columns: def.columns, rows: d.rows, capped: d.capped, ...(d.note ? { note: d.note } : {}), ...(d.error ? { error: d.error } : {}) });
  }
  return out;
}

export async function analyze(bundle: Bundle, opts: ScanOptions = {}): Promise<RunResult> {
  const ctx: AnalysisCtx = { version: bundle.server.versionNum, opts, profile: profileFor(opts.provider ?? bundle.provider), tls: bundle.connection.tls, local: bundle.connection.local, facts: bundle.facts };
  const datasets = datasetsFrom(bundle);
  const byId = Object.fromEntries(datasets.map((d) => [d.id, d]));
  const found: Finding[] = [];
  const checks: CheckResult[] = [];
  for (const def of CHECKS) {
    const { result, finding } = await evaluate(def, ctx, byId);
    checks.push(result);
    if (finding) found.push(finding);
  }
  const skipped = checks.filter((c) => c.status === "skipped").map((c) => ({ check: c.id, reason: c.reason ?? "" }));
  const vitals = vitalsFrom(bundle.vitals);
  return { findings: triage(found, datasets, vitals), checks, skipped, serverVersion: bundle.server.version, provider: ctx.profile.id, datasets, vitals, session: bundle.session };
}
