import { type CheckDef, pl, top, GB, MB } from "./checkdef.js";

const num = (v: unknown) => Number(v ?? 0);
const age = (iso: unknown) => (iso ? (Date.now() - new Date(String(iso)).getTime()) / 1000 : Infinity);

export const CHECKS_A: CheckDef[] = [
  // ───────── Queries
  { id: "queries.no_pgss", section: "queries", title: "Query statistics are collected", looks: "Whether pg_stat_statements is installed.", flags: "Info when it is missing.",
    run: ({ d }) => d.q_total?.note ? { severity: "info", title: "pg_stat_statements isn't installed",
      why: "Without it there is no per-query history to find slow or heavy statements.",
      fix: "Add it to shared_preload_libraries (restart), then CREATE EXTENSION pg_stat_statements." } : null },
  { id: "queries.dominant", section: "queries", title: "No single query dominates the workload", looks: "The share of total application query time taken by the top statement, after catalog and tooling queries are excluded.", flags: "Warning when one statement is 30% or more of at least 60 s of recorded application query time.", uses: ["q_total"],
    run: ({ ctx, rows }) => {
      const r = rows("q_total"); const t = r[0]; const minMs = ctx.opts.minWorkloadMs ?? 60_000;
      if (!t) return { note: "No application statements recorded yet." };
      if (num(t.workload_ms) < minMs) return { note: `Only ${(num(t.workload_ms) / 1000).toFixed(1)} s of query time is recorded, too little to judge. Scan again after the database has been busy.` };
      if (num(t.pct) < 30) return null;
      return { severity: "warning", title: `One query takes ${t.pct}% of your query time`, why: `Of ${Math.round(num(t.workload_ms) / 1000).toLocaleString()} s of recorded application query time, this one statement accounts for ${t.pct}% across ${num(t.calls).toLocaleString()} calls. It is the highest-leverage thing to optimise.`,
        fix: "EXPLAIN (ANALYZE, BUFFERS) it; look for seq scans, missing indexes, or N+1 call patterns.", evidence: top(r, 5) };
    } },
  { id: "queries.slow_average", section: "queries", title: "No query is slow on average", looks: "Statements called 5+ times whose mean time is high.", flags: "Warning for any averaging 1 second or more.", uses: ["q_mean"],
    run: ({ rows }) => {
      const r = rows("q_mean").filter((x) => num(x.mean_ms) >= 1000);
      return r.length ? { severity: "warning", title: `${r.length} ${pl(r.length, "query averages", "queries average")} over 1 second`, why: "Slow statements trip client timeouts and hold connections.",
        fix: "Get the plan with EXPLAIN (ANALYZE, BUFFERS) and add the index or rewrite it.", evidence: top(r) } : null;
    } },
  { id: "queries.temp_spill", section: "queries", title: "Queries don't spill to disk", looks: "Statements writing large temp files because work_mem is exceeded.", flags: "Info at roughly 800 MB or more of temp writes per statement.", uses: ["q_temp"],
    run: ({ rows }) => {
      const r = rows("q_temp").filter((x) => num(x.temp_bytes) >= 819_200_000);
      return r.length ? { severity: "info", title: `${r.length} ${pl(r.length, "query spills", "queries spill")} heavily to temp files`, why: "Sorts and hashes that exceed work_mem run much slower on disk.",
        fix: "Add an index that avoids the sort, or raise work_mem for that role, not globally.", evidence: top(r) } : null;
    } },
  { id: "queries.statements_evicted", section: "queries", title: "Query history isn't being evicted", looks: "Whether pg_stat_statements is dropping old statements.", flags: "Info when any statements were evicted.", uses: ["q_pgss"],
    run: ({ rows }) => { const r = rows("q_pgss")[0]; return r && num(r.dealloc) > 0 ? { severity: "info", title: `${num(r.dealloc).toLocaleString()} statements were evicted from tracking`,
      why: "The tracking table is full, so rarely-run queries lose their history.", fix: "Raise pg_stat_statements.max (needs a restart).", evidence: r } : null; } },

  // ───────── Tables
  { id: "tables.seq_scans", section: "tables", title: "Large tables are read via indexes", looks: "Tables over 50,000 rows read mostly by sequential scan.", flags: "Warning when seq scans exceed 100 and 5x the index scans.", uses: ["t_seq"],
    run: ({ rows }) => {
      const r = rows("t_seq").filter((x) => num(x.live_rows) > 50_000 && num(x.seq_scan) > 100 && num(x.seq_scan) > 5 * num(x.idx_scan));
      return r.length ? { severity: "warning", title: `${r.length} large ${pl(r.length, "table is", "tables are")} mostly read by sequential scan`, why: "Repeated full scans of big tables drive CPU and I/O load.",
        fix: "Find the filtered columns in pg_stat_statements and test a supporting index.", evidence: top(r) } : null;
    } },
  // Public basis: PostgreSQL docs, "Heap-Only Tuples (HOT)" (storage-hot) and the fillfactor storage parameter (CREATE TABLE).
  { id: "tables.low_hot_updates", section: "tables", title: "Updates are mostly HOT", looks: "The share of updates done as heap-only tuple (HOT) updates on tables with many updates.", flags: "Info when a table with 10,000+ updates since the stats reset has under 50% HOT updates.", uses: ["t_churn"],
    run: (x) => {
      const r = x.rows("t_churn").filter((t) => Number(t.updates ?? 0) >= 10_000 && t.hot_pct !== null && Number(t.hot_pct) < 50);
      if (!r.length) return null;
      return { severity: "info", title: `${r.length} update-heavy ${pl(r.length, "table has", "tables have")} few HOT updates`,
        why: "An update that can't be done as a HOT update writes a new entry into every index on the table, more WAL, and more for vacuum to clean up. An update can't be HOT when it changes an indexed column or the page has no free space.",
        fix: "If the updated columns don't need an index, drop those indexes. Otherwise leave free space in each page with a lower fillfactor, such as 90. It applies to pages written from now on; VACUUM FULL or pg_repack applies it to the whole table.",
        sql: r.slice(0, 10).map((t) => `ALTER TABLE ${t.table} SET (fillfactor = 90);  -- ${Number(t.updates).toLocaleString("en-US")} updates, ${t.hot_pct}% HOT`).join("\n"),
        evidence: r.slice(0, 20).map((t) => ({ table: t.table, updates: t.updates, hot_pct: t.hot_pct })) };
    } },
  { id: "tables.no_primary_key", section: "tables", title: "Every table has a primary key", looks: "Tables without a primary key.", flags: "Info for a table with 1,000+ rows or over 8 MB; smaller ones are only noted.", uses: ["t_nopk"],
    run: ({ rows }) => { const all = rows("t_nopk"); const r = all.filter((x) => num(x.est_rows) >= 1000 || num(x.bytes) >= 8 * MB);
      if (r.length) return { severity: "info", title: `${r.length} ${pl(r.length, "table has", "tables have")} no primary key`,
        why: "Breaks logical replication of updates and deletes, and makes rows hard to address safely.", fix: "Add a primary key, or REPLICA IDENTITY FULL if the table is published.", evidence: top(r) };
      return all.length ? { note: `${all.length} small ${pl(all.length, "table", "tables")} (under 1,000 rows) ${pl(all.length, "has", "have")} no primary key: ${all.slice(0, 5).map((x) => x.table).join(", ")}.` } : null; } },
  { id: "tables.stale_statistics", section: "tables", title: "Planner statistics are fresh", looks: "Tables with many changes since the last ANALYZE.", flags: "Warning when 20%+ of a 10k+ row table changed and it wasn't analyzed in the last day.", uses: ["t_stale"],
    run: ({ rows }) => {
      const r = rows("t_stale").filter((x) => num(x.live_rows) >= 10_000 && num(x.mod_pct) >= 20 && age(x.last_analyzed) > 86_400);
      return r.length ? { severity: "warning", title: `${r.length} ${pl(r.length, "table has", "tables have")} stale planner statistics`, why: "The planner picks bad plans when its statistics no longer match the data.",
        fix: "Run ANALYZE on them, and lower autovacuum_analyze_scale_factor on hot tables.", evidence: top(r) } : null;
    } },
  { id: "tables.bloat", section: "tables", title: "Tables aren't bloated", looks: "Measured wasted space in the largest tables (needs pgstattuple).", flags: "Warning at 40%+ bloat when the waste is at least 5% of the database (never under 8 MB, never required above 100 MB); critical at 60%+ when it is 1 GB or a fifth of the database.", uses: ["t_bloat", "cfg_version"],
    run: ({ ctx, rows }) => {
      const db = num(rows("cfg_version")[0]?.db_bytes);
      // A 60 MB table wasting 50 MB matters on a 500 MB volume and not at all on a 2 TB one, so the floor scales with the database.
      const min = ctx.opts.minBloatBytes ?? Math.max(8 * MB, Math.min(100 * MB, 0.05 * db));
      const r = rows("t_bloat").filter((x) => num(x.bloat_pct) >= 40 && num(x.wasted_bytes) >= min);
      if (!r.length) return null;
      const wasted = r.reduce((a, x) => a + num(x.wasted_bytes), 0);
      const crit = r.some((x) => num(x.bloat_pct) >= 60 && (num(x.wasted_bytes) >= GB || (db > 0 && num(x.wasted_bytes) >= 0.2 * db)));
      return { severity: crit ? "critical" : "warning", title: `${r.length} ${pl(r.length, "table is", "tables are")} heavily bloated (${Math.round(wasted / MB).toLocaleString()} MB wasted${db ? `, ${Math.round((100 * wasted) / db)}% of the database` : ""})`, why: "Wasted space slows scans, bloats caches and wastes disk.",
        fix: "Fix what blocks vacuum, then reclaim space with pg_repack (avoid VACUUM FULL on live tables).", evidence: top(r) };
    } },

  // ───────── Indexes
  { id: "indexes.invalid", section: "indexes", title: "No invalid indexes", looks: "Indexes left invalid by a failed CREATE INDEX CONCURRENTLY.", flags: "Warning for any.", uses: ["i_invalid"],
    run: ({ rows }) => { const r = rows("i_invalid"); return r.length ? { severity: "warning", title: `${r.length} invalid ${pl(r.length, "index", "indexes")}`, why: "It costs writes but is never used for reads.",
      fix: "DROP INDEX CONCURRENTLY it and recreate.", evidence: r } : null; } },
  { id: "indexes.unused", section: "indexes", title: "No large unused indexes", looks: "Indexes over 8 MB that were never scanned since the stats reset.", flags: "Info for any.", uses: ["i_unused"],
    run: ({ rows }) => { const r = rows("i_unused").filter((x) => num(x.bytes) > 8 * MB); return r.length ? { severity: "info", title: `${r.length} large ${pl(r.length, "index was", "indexes were")} never used`,
      why: "Unused indexes slow every write and take disk and cache.", fix: "Confirm the stats cover a full business cycle (and replicas), then DROP INDEX CONCURRENTLY.", evidence: top(r) } : null; } },
  { id: "indexes.duplicate", section: "indexes", title: "No duplicate indexes", looks: "Identical indexes on the same table.", flags: "Info when they waste 1 MB or more; warning at 100 MB. Smaller ones are only noted.", uses: ["i_dup"],
    run: ({ rows }) => { const all = rows("i_dup"); if (!all.length) return null; const waste = all.reduce((n, x) => n + num(x.bytes) * (1 - 1 / num(x.copies)), 0);
      if (waste < MB) return { note: `${all.length} ${pl(all.length, "set", "sets")} of duplicate indexes on tiny tables (${Math.round(waste / 1024)} KB wasted): ${all.slice(0, 3).map((x) => x.indexes).join("; ")}.` };
      return { severity: waste >= 100 * MB ? "warning" : "info", title: `${all.length} ${pl(all.length, "set", "sets")} of duplicate indexes (${Math.round(waste / MB)} MB wasted)`, why: "Each copy doubles the write cost for no read benefit.", fix: "Keep one, the primary key or unique one if there is such a one, and DROP INDEX CONCURRENTLY the others after checking that no constraint, replication setup or maintenance script refers to them by name.", evidence: top(all) }; } },
  { id: "indexes.redundant", section: "indexes", title: "No redundant (prefix) indexes", looks: "Non-unique indexes that are the leading columns of a longer index.", flags: "Info when the redundant index is 1 MB or more; smaller ones are only noted.", uses: ["i_redundant"],
    run: ({ rows }) => { const all = rows("i_redundant"); const r = all.filter((x) => num(x.bytes) >= MB);
      if (r.length) return { severity: "info", title: `${r.length} redundant ${pl(r.length, "index", "indexes")}`, why: "A longer index on the same columns already serves those queries.", fix: "Drop the shorter index after checking it isn't required by a constraint.", evidence: top(r) };
      return all.length ? { note: `${all.length} redundant ${pl(all.length, "index", "indexes")} on tiny tables (under 1 MB each): ${all.slice(0, 3).map((x) => x.redundant).join(", ")}. Not worth acting on yet.` } : null; } },
  { id: "indexes.fk_without_index", section: "indexes", title: "Foreign keys are indexed", looks: "Foreign-key columns with no supporting index.", flags: "Warning when a referencing table has 10k+ rows; info at 1,000+. Smaller tables are only noted.", uses: ["i_fk"],
    run: ({ rows }) => { const all = rows("i_fk"); const r = all.filter((x) => num(x.est_rows) >= 1000);
      if (r.length) return { severity: r.some((x) => num(x.est_rows) >= 10_000) ? "warning" : "info", title: `${r.length} foreign ${pl(r.length, "key has", "keys have")} no supporting index`,
        why: "Deleting or updating a referenced row scans the whole referencing table and can hold locks.", fix: "CREATE INDEX CONCURRENTLY on the referencing columns, largest tables first.", evidence: top(r) };
      return all.length ? { note: `${all.length} foreign ${pl(all.length, "key", "keys")} on small tables (under 1,000 rows) ${pl(all.length, "has", "have")} no index. Harmless at this size; add indexes as the tables grow.` } : null; } },

  // ───────── Schema & integrity
  { id: "schema.sequence_exhaustion", section: "schema", title: "Sequences are far from their maximum", looks: "How much of each sequence's range is used (integer keys run out at about 2.1 billion).", flags: "Warning at 70% used; critical at 90%.", uses: ["sch_seq"],
    run: ({ rows }) => {
      const all = rows("sch_seq"); const readable = all.filter((x) => x.readable);
      const hot = readable.filter((x) => num(x.pct_used) >= 70 && !x.cycle);
      if (hot.length) return { severity: hot.some((x) => num(x.pct_used) >= 90) ? "critical" : "warning", title: `${hot.length} ${pl(hot.length, "sequence is", "sequences are")} running out of numbers`,
        why: "When a sequence reaches its maximum, inserts start failing.", fix: "Migrate the column to bigint (ALTER SEQUENCE ... AS bigint, then the column) before it fills.", evidence: top(hot) };
      const blind = all.length - readable.length;
      return blind > 0 ? { note: `Checked ${readable.length} of ${all.length} sequences. Grant SELECT on the rest to include them.` } : null;
    } },
  { id: "schema.constraints_not_validated", section: "schema", title: "Constraints are validated", looks: "Constraints added NOT VALID that were never validated.", flags: "Info for any.", uses: ["sch_notvalid"],
    run: ({ rows }) => { const r = rows("sch_notvalid"); return r.length ? { severity: "info", title: `${r.length} ${pl(r.length, "constraint is", "constraints are")} not validated`, why: "Existing rows may still violate them; only new writes are checked.",
      fix: "Run ALTER TABLE ... VALIDATE CONSTRAINT (it takes a light lock).", evidence: top(r) } : null; } },
  { id: "schema.disabled_triggers", section: "schema", title: "No triggers are disabled", looks: "Triggers switched off.", flags: "Info for any.", uses: ["sch_triggers"],
    run: ({ rows }) => { const r = rows("sch_triggers"); return r.length ? { severity: "info", title: `${r.length} ${pl(r.length, "trigger is", "triggers are")} disabled`, why: "The logic they enforce is silently skipped.",
      fix: "Re-enable with ALTER TABLE ... ENABLE TRIGGER, or drop the ones you no longer need.", evidence: top(r) } : null; } },

  // ───────── Blocked transactions
  { id: "blocking.lock_waits", section: "blocking", title: "Nothing is blocked on locks", looks: "Queries currently waiting for a lock held by another session.", flags: "Warning; critical if anything waits 30 s or more.", uses: ["b_blocked"],
    run: ({ rows }) => { const r = rows("b_blocked"); if (!r.length) return null;
      return { severity: r.some((x) => num(x.waiting_s) >= 30) ? "critical" : "warning", title: `${r.length} ${pl(r.length, "query is", "queries are")} blocked on locks`, why: "Blocked queries pile up and can exhaust connections.",
        fix: "Inspect the blocking PID; pg_cancel_backend it if safe, and use lock_timeout in migrations.", evidence: top(r) }; } },
  { id: "blocking.idle_in_transaction", section: "blocking", title: "No sessions idle in a transaction", looks: "Sessions that opened a transaction and went quiet.", flags: "Warning at 5 minutes idle.", uses: ["b_idle"],
    run: ({ ctx, rows }) => { const min = ctx.opts.idleTxnSeconds ?? 300; const r = rows("b_idle").filter((x) => num(x.idle_s) >= min);
      return r.length ? { severity: "warning", title: `${r.length} ${pl(r.length, "session is", "sessions are")} idle in a transaction`, why: "They hold locks and pin the vacuum horizon for the whole database.",
        fix: "Find the client that forgot to COMMIT, and set idle_in_transaction_session_timeout.", evidence: top(r) } : null; } },
  { id: "blocking.long_running_queries", section: "blocking", title: "No very long-running queries", looks: "Statements that have been executing for a long time.", flags: "Info at 5 minutes; warning at 30 minutes.", uses: ["b_running"],
    run: ({ rows }) => { const r = rows("b_running").filter((x) => num(x.running_s) >= 300); if (!r.length) return null;
      return { severity: r.some((x) => num(x.running_s) >= 1800) ? "warning" : "info", title: `${r.length} ${pl(r.length, "query has", "queries have")} been running over 5 minutes`, why: "Long statements hold snapshots (blocking vacuum) and resources.",
        fix: "Confirm they are expected; otherwise pg_cancel_backend and add a statement_timeout.", evidence: top(r) }; } },
  { id: "blocking.prepared_transactions", section: "blocking", title: "No stuck prepared transactions", looks: "Two-phase-commit transactions left prepared.", flags: "Warning after 5 minutes; critical after 1 hour.", uses: ["b_prepared"],
    run: ({ rows }) => { const r = rows("b_prepared").filter((x) => num(x.age_s) >= 300); if (!r.length) return null;
      return { severity: r.some((x) => num(x.age_s) >= 3600) ? "critical" : "warning", title: `${r.length} prepared ${pl(r.length, "transaction is", "transactions are")} stuck`, why: "They hold locks and block vacuum until resolved.",
        fix: "COMMIT PREPARED or ROLLBACK PREPARED, then fix the transaction manager that lost them.", evidence: r }; } },
  { id: "blocking.vacuum_horizon", section: "blocking", title: "Nothing is holding back vacuum", looks: "The oldest xmin held by a session, slot, prepared transaction or standby.", flags: "Warning at 10 million transactions old; critical at 100 million.", uses: ["b_xmin"],
    run: ({ rows }) => { const r = rows("b_xmin"); const t = r[0]; if (!t || num(t.xmin_age) < 10_000_000) return null;
      return { severity: num(t.xmin_age) >= 100_000_000 ? "critical" : "warning", title: `${t.holder} is holding back vacuum (${num(t.xmin_age).toLocaleString()} transactions old)`,
        why: "Dead rows newer than it can't be removed anywhere in the database.", fix: "End or fix the oldest holder: close the session, drop the stale slot, or resolve the prepared transaction.", evidence: top(r, 5) }; } },

  // ───────── Connections
  { id: "connections.saturation", section: "connections", title: "Connections are below the limit", looks: "Client connections as a share of max_connections.", flags: "Warning at 80%; critical at 90%.", uses: ["c_limits"],
    run: ({ rows }) => { const r = rows("c_limits")[0]; if (!r || num(r.used_pct) < 80) return null;
      return { severity: num(r.used_pct) >= 90 ? "critical" : "warning", title: `Connections at ${r.used_pct}% of the limit (${r.in_use}/${r.max_connections})`, why: "At 100% new clients get 'too many clients' errors.",
        fix: "Put a pooler (PgBouncer, pgcat) in transaction mode in front and cap app pool sizes.", evidence: r }; } },
  { id: "connections.idle_sessions", section: "connections", title: "Idle connections are under control", looks: "Many mostly-idle connections.", flags: "Info at 50+ idle and 40%+ of max_connections.", uses: ["c_limits"],
    run: ({ rows }) => { const r = rows("c_limits")[0]; if (!r || num(r.idle) < 50 || num(r.idle) < 0.4 * num(r.max_connections)) return null;
      return { severity: "info", title: `${r.idle} idle connections (${Math.round((100 * num(r.idle)) / num(r.max_connections))}% of the limit)`, why: "Idle connections still use memory and count against max_connections.",
        fix: "Use a pooler and shrink application pool sizes.", evidence: r }; } },
  { id: "connections.plaintext_sessions", section: "connections", title: "Remote clients use TLS", looks: "Remote sessions connected without encryption (excludes this scan and provider services).", flags: "Warning for any.", uses: ["c_ssl"],
    run: ({ rows }) => { const r = rows("c_ssl").filter((x) => x.remote && !x.encrypted); const n = r.reduce((a, x) => a + num(x.sessions), 0);
      return n ? { severity: "warning", title: `${n} remote ${pl(n, "connection isn't", "connections aren't")} using TLS`, why: "Credentials and data cross the network unencrypted.",
        fix: "Require TLS (hostssl in pg_hba.conf, or your provider's enforce-SSL setting) and use sslmode=require.", evidence: r } : null; } },
  { id: "connections.server_accepts_plaintext", section: "connections", title: "The server enforces TLS", looks: "Whether this scan could only connect without TLS.", flags: "Warning when a remote server accepted an unencrypted connection.",
    run: ({ ctx }) => ctx.local || ctx.tls ? null : { severity: "warning", title: "The database accepted an unencrypted connection", why: "Credentials and data can cross the network in clear text.",
      fix: "Enforce TLS at the server or provider, and use sslmode=require in clients." } },
];
