import { type CheckDef, type X, pl, GB } from "./checkdef.js";

const num = (v: unknown) => Number(v ?? 0);
const gb = (n: number) => (n >= GB ? `${(n / GB).toFixed(n >= 10 * GB ? 0 : 1)} GB` : `${Math.round(n / 1024 ** 2)} MB`);
const HOUR_MS_WINDOW = 1800; // need at least 30 minutes of statistics to judge a rate

const UP = {
  supabase: "In the Supabase dashboard, open Project Settings, then Compute and Disk, and pick a larger compute size.",
  neon: "In the Neon console, raise the autoscaling maximum for this endpoint, or choose a larger fixed compute.",
  generic: "Move to an instance with more memory and vCPUs. On RDS or Cloud SQL that means changing the instance class, which restarts or fails over briefly.",
} as const;
const OUT = {
  supabase: "Add a read replica from the dashboard and send read-only traffic to it.",
  neon: "Add a read replica compute and point read-only traffic at it.",
  generic: "Add a streaming replica and route read-only queries to it (from the application or a pooler).",
} as const;
const provider = (x: X) => (x.ctx.profile.id in UP ? x.ctx.profile.id : "generic") as keyof typeof UP;

/** Share of active sessions (other than the scanner) with a given wait type, from the wait-event snapshot. */
function waitShare(x: X, type: string): { share: number; active: number; n: number } {
  const active = Math.max(0, num(x.rows("c_limits")[0]?.active) - 1); // the scanner's own query is active too
  const n = x.rows("c_waits").filter((r) => r.type === type).reduce((a, r) => a + num(r.sessions), 0);
  return { share: active ? n / active : 0, active, n };
}

/** Capacity & scaling. Each finding says what to try first, and what to scale if that isn't enough. */
export const CHECKS_D: CheckDef[] = [
  { id: "capacity.working_set", section: "capacity", title: "The working data fits in memory", looks: "Database size against shared_buffers / effective_cache_size, and the share of reads served from cache.", flags: "Warning when data is over twice the memory and the cache hit rate is under 97%; info under 99%.", uses: ["cap_sizing", "cap_load"],
    run: (x) => {
      const s = x.rows("cap_sizing")[0], l = x.rows("cap_load")[0]; if (!s || !l || l.cache_hit_pct === null || num(l.window_s) < HOUR_MS_WINDOW) return null;
      const mem = Math.max(num(s.shared_buffers_bytes), num(s.effective_cache_bytes)), db = num(s.db_bytes), hit = num(l.cache_hit_pct);
      if (db < 2 * mem || hit >= 99) return null;
      return { severity: hit < 97 ? "warning" : "info", title: `Data (${gb(db)}) is much larger than memory (${gb(mem)}), and ${(100 - hit).toFixed(1)}% of reads go to disk`,
        why: "Reads that miss the cache wait on storage. As the data grows past memory, latency rises and disk I/O becomes the limit.",
        fix: `Tune first: drop unused indexes and add missing ones so fewer pages are read, and check the largest queries in Queries. Then scale up memory. ${UP[provider(x)]}`, evidence: { db_bytes: db, shared_buffers_bytes: num(s.shared_buffers_bytes), effective_cache_bytes: num(s.effective_cache_bytes), cache_hit_pct: hit, disk_read_bps: num(l.disk_read_bps) } };
    } },
  { id: "capacity.io_wait", section: "capacity", title: "Sessions aren't waiting on disk", looks: "The share of currently active sessions waiting on I/O, from a wait-event snapshot.", flags: "Warning when 40% or more of at least 3 active sessions wait on I/O.", uses: ["c_waits", "c_limits"],
    run: (x) => {
      const w = waitShare(x, "IO"); if (w.active < 3 || w.share < 0.4) return null;
      return { severity: "warning", title: `${w.n} of ${w.active} active sessions are waiting on disk I/O`,
        why: "This is a snapshot, so run the checkup again a few times to confirm. If it keeps showing, storage speed (IOPS or throughput) is the limit, not the queries' CPU.",
        fix: `Tune first: find the queries reading the most from disk (Queries) and index them. Then move to faster or larger storage (more provisioned IOPS, or a bigger instance which usually brings more). ${UP[provider(x)]}`, evidence: x.rows("c_waits").filter((r) => r.type === "IO") };
    } },
  { id: "capacity.cpu_bound", section: "capacity", title: "Active sessions aren't all on CPU", looks: "Active sessions that are running (no wait event) against max_connections, from a snapshot.", flags: "Info when at least 8 sessions, and a quarter of max_connections, are running on CPU together.", uses: ["c_waits", "c_limits"],
    run: (x) => {
      const w = waitShare(x, "Running on CPU"), max = num(x.rows("c_limits")[0]?.max_connections);
      if (w.n < 8 || w.n < 0.25 * max || w.share < 0.6) return null;
      return { severity: "info", title: `${w.n} sessions are running on CPU at the same moment`,
        why: "Many queries executing at once compete for the same cores. If the host's CPU is also near 100% (check your provider's metrics, SQL can't see it), the server is CPU-bound.",
        fix: `Tune first: the top statements in Queries usually account for most of the CPU. If they are already efficient, scale up vCPUs. ${UP[provider(x)]}`, evidence: x.rows("c_waits").slice(0, 5) };
    } },
  { id: "capacity.temp_spill", section: "capacity", title: "Queries aren't spilling to temp files heavily", looks: "Temp file volume per hour since the last statistics reset.", flags: "Info at 1 GB per hour or more; warning at 5 GB.", uses: ["cap_load"],
    run: (x) => {
      const l = x.rows("cap_load")[0]; const perHour = num(l?.temp_bytes_per_hour); if (!l || num(l.window_s) < HOUR_MS_WINDOW || perHour < GB) return null;
      return { severity: perHour >= 5 * GB ? "warning" : "info", title: `About ${gb(perHour)} of temp files are written per hour`,
        why: "Sorts and hash joins that don't fit in work_mem go to disk, which is far slower than memory and adds write load.",
        fix: `Tune first: raise work_mem for the roles running the big reports (alter role reporting set work_mem = '128MB'), and look at q_temp in Queries. If that isn't enough, add memory. ${UP[provider(x)]}`, evidence: l };
    } },
  { id: "capacity.read_replica", section: "capacity", title: "Reads and writes are balanced, or there is a replica", looks: "Read-to-write row ratio, when the database is also showing memory, disk or CPU pressure and has no replica.", flags: "Info when reads are 5 times writes (or more), pressure signals are present, and no standby is attached.", uses: ["cap_load", "c_waits", "c_limits"],
    run: (x) => {
      const l = x.rows("cap_load")[0]; if (!l || num(l.window_s) < HOUR_MS_WINDOW || x.rows("r_standby").length) return null;
      const ratio = num(l.tup_read) / Math.max(1, num(l.tup_written));
      const pressure = (l.cache_hit_pct !== null && num(l.cache_hit_pct) < 99) || waitShare(x, "IO").share >= 0.4 || waitShare(x, "Running on CPU").n >= 8;
      if (ratio < 5 || !pressure) return null;
      return { severity: "info", title: `Reads outnumber writes ${Math.round(ratio)} to 1, with no replica to share the load`,
        why: "A read-heavy workload under pressure is where scaling out helps most: a replica serves reports and dashboards without touching the primary. It does nothing for writes, so if writes are the limit, a bigger primary is the answer.",
        fix: `Tune first (indexes, caching in the application). Then scale out. ${OUT[provider(x)]} Keep the primary for writes and for reads that must be current.`, evidence: { rows_read: num(l.tup_read), rows_written: num(l.tup_written), ratio: Math.round(ratio) } };
    } },
  { id: "capacity.large_table", section: "capacity", title: "No single table dominates the database", looks: "The largest table's size and its share of the database.", flags: "Info at 100 GB, or 20 GB when it is 60% or more of the database.", uses: ["cap_sizing"],
    run: (x) => {
      const s = x.rows("cap_sizing")[0]; if (!s) return null; const t = num(s.largest_table_bytes), db = num(s.db_bytes);
      if (!(t >= 100 * GB || (t >= 20 * GB && t >= 0.6 * db))) return null;
      return { severity: "info", title: `One table holds ${gb(t)} (${Math.round((100 * t) / Math.max(1, db))}% of the database)`,
        why: "Very large tables make vacuum, index builds, backups and restores slow, and every query on them scans more data.",
        fix: "Split it by time or key with declarative partitioning, then archive or drop old partitions instead of deleting rows. Plan it before the table doubles: moving data into partitions gets harder as it grows.", evidence: s };
    } },
  { id: "capacity.autovacuum_saturated", section: "capacity", title: "Autovacuum workers have spare capacity", looks: "Autovacuum workers running now against autovacuum_max_workers.", flags: "Info when every worker is busy at scan time.", uses: ["cap_workers"],
    run: (x) => {
      const w = x.rows("cap_workers")[0]; if (!w || num(w.max_workers) < 1 || num(w.running) < num(w.max_workers)) return null;
      return { severity: "info", title: `All ${num(w.max_workers)} autovacuum ${pl(num(w.max_workers), "worker is", "workers are")} busy right now`,
        why: "When every worker is occupied, other tables wait for their turn. It's a snapshot, but if it keeps showing, cleanup is falling behind the write rate.",
        fix: "Tune first: raise autovacuum_max_workers (restart needed) and autovacuum_vacuum_cost_limit, and lower the scale factor on the biggest tables. If vacuum is still I/O-bound after that, storage is the limit.", evidence: w };
    } },

  // Disk: what SQL can and cannot see
  { id: "capacity.footprint", section: "capacity", title: "Footprint on disk is known", looks: "This database, the other databases on the server and WAL, added up. Postgres cannot see the volume's size or free space.", flags: "Never flags on its own. Warning when WAL alone is over half the size of the data, which usually means retention is stuck. The total is for you to compare with your volume.", uses: ["cap_footprint"],
    run: (x) => {
      const f = x.rows("cap_footprint")[0]; if (!f) return null;
      const db = num(f.db_bytes), other = num(f.other_dbs_bytes), wal = num(f.wal_bytes), total = num(f.total_bytes);
      const parts = [`this database ${gb(db)}`, other ? `other databases ${gb(other)}` : "", `WAL ${gb(wal)}`].filter(Boolean).join(", ");
      if (wal > 256 * 1024 ** 2 && wal > 0.5 * (db + other)) return { severity: "warning", title: `WAL takes ${gb(wal)} on disk, more than half the size of the data`,
        why: "WAL should recycle at around max_wal_size. When it keeps growing, a replication slot, a failing archiver or a stalled standby is pinning it, and it will fill the volume.", fix: "Look at Replication & WAL: inactive slots, archiver failures and wal_keep_size. The footprint here is at least " + gb(total) + ".", evidence: f };
      const temp = num(f.window_s) >= 3600 ? ` and temp files (about ${gb(num(f.temp_bytes_per_day))}/day)` : "";
      return { note: `At least ${gb(total)} on the volume (${parts}), plus logs${temp}. Free space isn't visible from SQL: compare with your host or provider metrics.` };
    } },

  // pg_net
  { id: "extensions.pg_net_responses", section: "extensions", title: "pg_net's response table is kept small", looks: "The size and dead-row share of net._http_response, and how many requests are waiting in net.http_request_queue.", flags: "Warning when the response table is over 100 MB, or over 10 MB with more dead than live rows; critical at 1 GB. Warning when 1,000+ requests are queued.", uses: ["net_queue"],
    run: (x) => {
      const q = x.rows("net_queue")[0]; if (!q) return null;
      const bytes = num(q.response_bytes), live = num(q.response_rows), dead = num(q.response_dead_rows), queued = num(q.queued);
      if (queued >= 1000) return { severity: queued >= 10_000 ? "critical" : "warning", title: `${queued.toLocaleString()} pg_net requests are waiting to be sent`,
        why: "The pg_net background worker sends requests from this queue in batches. A backlog means webhooks and edge-function calls are going out late, or not at all if the worker has stopped.",
        fix: "Check that the worker is running (select * from pg_stat_activity where backend_type like '%pg_net%'), raise pg_net.batch_size if it is simply behind, and look for a slow or unreachable destination.", evidence: q };
      const bloated = bytes >= 10 * 1024 ** 2 && dead > live;
      if (bytes < 100 * 1024 ** 2 && !bloated) return null;
      return { severity: bytes >= GB ? "critical" : "warning", title: `pg_net's response table is ${gb(bytes)}${bloated ? ` and mostly dead rows (${dead.toLocaleString()} dead, ${live.toLocaleString()} live)` : ""}`,
        why: "pg_net inserts a row per response and deletes rows older than pg_net.ttl (default 6 hours). With heavy webhook or trigger traffic the deletes outrun autovacuum, the table fills with dead rows, and every insert and the TTL delete itself get slower. This is one of the most common sources of unexplained disk growth on Supabase.",
        fix: "Vacuum it now, then keep it small: lower the TTL (alter role postgres set pg_net.ttl = '1 hour'; then select net.worker_restart();), or make autovacuum much more aggressive on the table.",
        sql: "-- reclaim dead rows now (does not lock out writes)\nVACUUM (VERBOSE, ANALYZE) net._http_response;\n\n-- keep fewer responses: 1 hour instead of the 6 hour default\nALTER ROLE postgres SET pg_net.ttl = '1 hour';\nSELECT net.worker_restart();\n\n-- and let autovacuum keep up with the churn\nALTER TABLE net._http_response SET (autovacuum_vacuum_scale_factor = 0.01, autovacuum_vacuum_cost_delay = 0);\n", evidence: q };
    } },

  // pg_cron
  { id: "extensions.cron_history", section: "extensions", title: "pg_cron run history is kept small", looks: "The size of cron.job_run_details, where pg_cron logs every run.", flags: "Info at 100 MB; warning at 1 GB.", uses: ["cron_history"],
    run: (x) => {
      const h = x.rows("cron_history")[0]; const b = num(h?.bytes); if (!h || b < 100 * 1024 ** 2) return null;
      return { severity: b >= GB ? "warning" : "info", title: `pg_cron's run history is ${gb(b)}`,
        why: "pg_cron logs every run and never deletes anything. A job that runs each minute adds over half a million rows a year, which slows the table and adds to backups.",
        fix: "Delete old rows and schedule a nightly cleanup with cron.schedule, or turn off logging for the busiest jobs with cron.log_run = off.", evidence: h };
    } },
  { id: "extensions.cron_failures", section: "extensions", title: "pg_cron jobs are succeeding", looks: "Scheduled jobs with failed runs in the last 7 days.", flags: "Warning when any job failed. Needs the job owner or a superuser, because pg_cron hides other roles' jobs.", uses: ["cron_failures"],
    run: (x) => {
      const r = x.rows("cron_failures"); if (!r.length) return null;
      return { severity: "warning", title: `${r.length} scheduled ${pl(r.length, "job has", "jobs have")} failed runs this week`,
        why: "A failing scheduled job usually means work isn't happening: cleanups, rollups, refreshes or partition maintenance silently stop.",
        fix: "Read the latest message in the evidence, fix the job's SQL or permissions, and check its history with select * from cron.job_run_details where jobid = <id> order by start_time desc.", evidence: r.slice(0, 10) };
    } },

  // ── Read replicas and replication that stopped ──
  { id: "replication.receiver_down", section: "replication", title: "This replica is receiving WAL from its primary", looks: "On a standby: whether the WAL receiver is running and streaming, and how long since it heard from the primary.", flags: "Critical when a streaming standby has no active receiver; warning when it hasn't heard from the primary in 2 minutes.", uses: ["r_receiver"],
    run: (x) => {
      const r = x.rows("r_receiver")[0]; if (!r || !r.expects_streaming) return null;
      if (num(r.receivers) === 0 || r.status !== "streaming") return { severity: "critical", title: `This replica has stopped receiving WAL${r.status ? ` (receiver status: ${r.status})` : ""}`,
        why: "The replica is frozen at the last data it received. Reads from it are stale and growing staler, and if the primary fails now, everything since is missing.",
        fix: "Check the standby's log for the reason (network, a removed WAL segment, an authentication change, or a dropped slot). If the primary already discarded the WAL it needs, the replica must be rebuilt from a fresh base backup. On a managed provider, look at the replica's status in the dashboard and replace it if it stays broken.", evidence: r };
      if (r.secs_since_msg !== null && num(r.secs_since_msg) > 120) return { severity: "warning", title: `No message from the primary for ${Math.round(num(r.secs_since_msg) / 60)} minutes`,
        why: "A healthy link exchanges messages every few seconds even when nothing is being written. Silence means the connection may be half-dead.", fix: "Check the network path between the two servers, and wal_sender_timeout on the primary and wal_receiver_timeout here.", evidence: r };
      return null;
    } },
  { id: "replication.replay_paused", section: "replication", title: "Replay is running on this replica", looks: "Whether replay of received WAL is paused on a standby.", flags: "Warning when paused.", uses: ["r_receiver"],
    run: (x) => { const r = x.rows("r_receiver")[0]; return r && r.paused ? { severity: "warning", title: "WAL replay is paused on this replica",
      why: "The replica keeps receiving WAL but stops applying it, so reads go stale. It's usually a maintenance step someone forgot to undo.", fix: "Resume it with select pg_wal_replay_resume(); once you are sure that is safe.", evidence: r } : null; } },
  { id: "replication.replica_backlog", section: "replication", title: "This replica applies WAL as fast as it receives it", looks: "WAL received but not yet applied on a standby.", flags: "Warning at 256 MB; critical at 2 GB.", uses: ["r_receiver"],
    run: (x) => {
      const r = x.rows("r_receiver")[0]; const b = num(r?.apply_backlog_bytes); if (!r || b < 256 * 1024 ** 2) return null;
      return { severity: b >= 2 * GB ? "critical" : "warning", title: `The replica has ${gb(b)} of WAL received but not applied`,
        why: "Replay is single-threaded, and it stalls behind long queries that conflict with it or a slow disk. Reads see data that is that far behind.",
        fix: "Look at recovery conflicts and long-running queries on the replica first. Then check its disk speed against the primary's, and consider a replica of the same size as the primary.", evidence: r };
    } },
  { id: "replication.recovery_conflicts", section: "replication", title: "Queries on this replica aren't being cancelled", looks: "Recovery conflicts recorded on a standby.", flags: "Warning at 5 or more cancelled queries.", uses: ["r_conflicts"],
    run: (x) => {
      const r = x.rows("r_conflicts")[0]; if (!r || num(r.total) < 5) return null;
      const top = ["snapshot", "lock", "bufferpin", "deadlock", "tablespace"].sort((a, b) => num(r[b]) - num(r[a]))[0];
      return { severity: "warning", title: `${num(r.total)} queries on this replica were cancelled by recovery conflicts`,
        why: "Replay has to remove old row versions and take locks, and a long query on the replica can hold them up. Postgres either delays replay or cancels the query; here it cancelled.",
        fix: `Most cancellations are "${top}". Options, each with a trade-off: raise max_standby_streaming_delay (replay waits longer, so the replica lags more); turn on hot_standby_feedback (the primary keeps old rows longer, which can bloat it); or move long analytical queries to a dedicated replica. Keep queries on the replica short where you can.`, evidence: r };
    } },
  { id: "replication.sync_standby_missing", section: "replication", title: "The synchronous standby is connected", looks: "synchronous_standby_names against the standbys actually connected.", flags: "Critical when synchronous replication is configured and no synchronous standby is connected.", uses: ["r_syncstandby"],
    run: (x) => {
      const r = x.rows("r_syncstandby")[0]; const names = String(r?.names ?? "").trim(); if (!r || !names || num(r.connected) > 0) return null;
      if (x.ctx.profile.internalSyncStandbys.some((n) => names === n || names.includes(n))) return { note: `synchronous_standby_names is "${names}", which is the provider's own replication machinery, not a standby you run.` };
      return { severity: "critical", title: "Synchronous replication is on, but no synchronous standby is connected",
        why: "Every commit waits for a standby to confirm it. With none connected, writes hang until one returns or you change the setting, so the application looks frozen.",
        fix: "Reconnect the standby, or remove it from synchronous_standby_names (alter system set synchronous_standby_names = ''; select pg_reload_conf();) to let commits through, and accept the weaker durability until it is back.", evidence: r };
    } },
  { id: "replication.standby_state", section: "replication", title: "Connected standbys are streaming", looks: "The state of each standby in pg_stat_replication.", flags: "Warning for a standby that is not streaming and is more than 16 MB behind, or is starting or in backup.", uses: ["r_standby"],
    run: (x) => {
      const r = x.rows("r_standby").filter((s) => s.state !== "streaming" && (s.state !== "catchup" || num(s.replay_bytes) > 16 * 1024 ** 2)); if (!r.length) return null;
      return { severity: "warning", title: `${r.length} ${pl(r.length, "standby is", "standbys are")} not streaming (${[...new Set(r.map((s) => s.state))].join(", ")})`,
        why: "A standby in catch-up is still working through backlog, and one that stays there is losing the race with the primary's write rate.", fix: "If it doesn't reach 'streaming' soon, check its log and the primary's WAL retention (max_wal_size, wal_keep_size, or a slot) so the WAL it needs still exists.", evidence: r.slice(0, 5) };
    } },

  // ── Stale connections ──
  { id: "connections.stale_sessions", section: "connections", title: "No connections are stale", looks: "Sessions idle for more than 30 minutes, and the keepalive and timeout settings that would end a dead one.", flags: "Info at 5 or more; warning at 20 or more, or when they are hours old with keepalives at the OS default.", uses: ["c_stale"],
    run: (x) => {
      const rows = x.rows("c_stale"), n = rows.reduce((a, r) => a + num(r.sessions), 0), oldest = Math.max(0, ...rows.map((r) => num(r.oldest_idle_s)));
      if (n < 5) return null;
      const set = (name: string) => x.rows("c_timeouts").find((r) => r.name === name)?.setting;
      const osDefault = String(set("tcp_keepalives_idle") ?? "0") === "0";
      return { severity: n >= 20 || (osDefault && oldest >= 4 * 3600) ? "warning" : "info", title: `${n} connections have been idle for over 30 minutes (longest ${oldest >= 86400 ? Math.round(oldest / 86400) + " days" : Math.round(oldest / 3600) + " hours"})`,
        why: "Idle is normal for a connection pool, but a client that crashed or lost its network leaves a session that looks identical. Postgres only notices when the operating system's keepalive fires, which defaults to two hours or more. Until then each one holds a connection slot and memory.",
        fix: "First check that they're dead, not pooled on purpose: compare with the application's pool size. Then make dead peers drop quickly: set tcp_keepalives_idle = 60, tcp_keepalives_interval = 10 and tcp_keepalives_count = 6, and on PostgreSQL 14+ set client_connection_check_interval = '10s' so running queries stop when the client has gone. Set your pool's idle timeout below the firewall's. idle_session_timeout (PostgreSQL 14+) also works, but it closes healthy idle connections too, so use it only if your clients reconnect cleanly.",
        sql: "-- self-managed servers (managed providers: set these in the dashboard's database settings)\nALTER SYSTEM SET tcp_keepalives_idle = 60;\nALTER SYSTEM SET tcp_keepalives_interval = 10;\nALTER SYSTEM SET tcp_keepalives_count = 6;\nALTER SYSTEM SET client_connection_check_interval = '10s';  -- PostgreSQL 14+\nSELECT pg_reload_conf();\n",
        evidence: rows.slice(0, 10) };
    } },
];
