import { type CheckDef, pl, top, GB } from "./checkdef.js";

const num = (v: unknown) => Number(v ?? 0);
const ts = (v: unknown) => (v ? new Date(String(v)).getTime() : 0);

/** Final-release dates per PostgreSQL major version (postgresql.org/support/versioning, checked Sept 2026). */
export const EOL: Record<number, string> = { 12: "2024-11-21", 13: "2025-11-13", 14: "2026-11-12", 15: "2027-11-11", 16: "2028-11-09", 17: "2029-11-08", 18: "2030-11-14" };
export function eolStatus(versionNum: number, now = Date.now()) {
  const major = Math.floor(versionNum / 10000);
  const date = major <= 11 ? "2023-11-09" : EOL[major];
  if (!date) return { major, date: null as string | null, daysLeft: null as number | null };
  return { major, date, daysLeft: Math.floor((new Date(date).getTime() - now) / 86_400_000) };
}

