// Pure module (no Node/pg imports) so the web app can re-run it on stored reports.
//
// Checks report one symptom each. Triage reads them together and decides what to do first: which finding causes
// another, which advice would be wrong until something else is fixed, and which findings rest on too little history
// to act on. Every rule follows from documented PostgreSQL behaviour:
// - Vacuum can't remove a row version that any open transaction or slot might still see (Routine Vacuuming, 25.1.2;
//   pg_stat_activity.backend_xmin / backend_xid; pg_replication_slots.xmin).
// - Sequential scans read dead row versions too, so dead rows slow them (pg_stat_user_tables.n_dead_tup).
// - The planner chooses plans from pg_statistic, which ANALYZE refreshes (Planner Statistics, 14.2).
// - Index usage counters start from the last statistics reset (pg_stat_user_indexes.idx_scan, pg_stat_reset).
// - A session waiting on a lock keeps its connection (pg_stat_activity.wait_event_type = 'Lock').
import type { Finding, Priority, Severity } from "./types.js";
import type { Dataset, Vital } from "./sections.js";

export const PRIORITIES: Priority[] = ["now", "next", "watch", "ignore"];
export const PRIORITY_LABEL: Record<Priority, string> = { now: "Fix now", next: "Fix next", watch: "Watch", ignore: "Safe to ignore for now" };
const DEFAULT: Record<Severity, Priority> = { critical: "now", warning: "next", info: "watch" };
const SEV: Severity[] = ["critical", "warning", "info"];

const num = (v: unknown) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const lc = (t: string) => t.charAt(0).toLowerCase() + t.slice(1);
const fmtN = (n: number) => Math.round(n).toLocaleString("en-US");
const span = (s: number) => (s < 7200 ? `${Math.max(1, Math.round(s / 60))} minutes` : s < 172_800 ? `${Math.round(s / 3600)} hours` : `${Math.round(s / 86_400)} days`);
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
/** True when SQL text mentions the table, with or without its schema or quotes. */
function mentions(sql: unknown, table: string): boolean {
  const name = table.includes(".") ? table.slice(table.indexOf(".") + 1) : table;
  return new RegExp(`(^|[^\\w$])"?${esc(name)}"?($|[^\\w$])`, "i").test(String(sql ?? ""));
}
const tablesIn = (f: Finding | undefined): string[] => (Array.isArray(f?.evidence) ? f!.evidence.map((r) => String(r.table ?? "")).filter(Boolean) : []);
const list = (names: string[], max = 3) => names.slice(0, max).join(", ") + (names.length > max ? ` and ${names.length - max} more` : "");

const HOLDS_VACUUM = ["vacuum.dead_tuples", "tables.bloat", "vacuum.xid_wraparound", "vacuum.multixact_wraparound", "vacuum.table_freeze_pressure"];
const QUERY_FINDINGS = ["queries.dominant", "queries.slow_average"];
const CAPACITY = ["capacity.cpu_bound", "capacity.working_set", "capacity.io_wait", "capacity.read_replica"];
/** Below this many transactions, an open transaction hasn't held vacuum back long enough to explain dead rows. */
const HORIZON_MIN = 100_000;

/**
 * Returns the findings with priority, cause and note set, ordered: fix now, fix next, watch, safe to ignore, and
 * within each, a cause before what it causes. Recomputes from scratch, so it can run again on a stored report.
 */
export function triage(input: Finding[], datasets: Dataset[], vitals: Vital[] = []): Finding[] {
  const fs: Finding[] = input.map(({ priority: _p, cause: _c, note: _n, ...f }) => ({ ...f, priority: DEFAULT[f.severity] ?? "watch" }));
  const by = (id: string) => fs.find((f) => f.id === id);
  const rows = (id: string) => datasets.find((d) => d.id === id)?.rows ?? [];
  const notes = new Map<string, string[]>();
  const note = (f: Finding, s: string) => notes.set(f.id, [...(notes.get(f.id) ?? []), s]);
  const rank = (p: Priority) => PRIORITIES.indexOf(p);
  /** `cause` explains `effect`: fix the cause first, so it is at least as urgent and is listed before it. */
  const link = (cause: Finding, effect: Finding) => {
    if (cause === effect || effect.cause) return;
    effect.cause = cause.id;
    if (rank(cause.priority!) > rank(effect.priority!)) cause.priority = effect.priority;
  };

  // Dead rows per table, for naming tables in notes.
  const deadPct = new Map(rows("v_dead").map((r) => [String(r.table), num(r.dead_pct)]));
  const dead = by("vacuum.dead_tuples");
  const deadTables = tablesIn(dead);

  // 1. Something is holding back vacuum, and there are dead rows, bloat or rising transaction ID age.
  const top = rows("b_xmin")[0];
  const horizon = by("blocking.vacuum_horizon");
  let holder: Finding | undefined;
  if (top && (horizon || num(top.xmin_age) >= HORIZON_MIN)) {
    const ref = String(top.ref ?? "");
    const pidIn = (id: string) => rows(id).some((r) => String(r.pid) === ref);
    const session = top.holder === "Backend session";
    holder =
      (session && pidIn("b_idle") ? by("blocking.idle_in_transaction") : undefined)
      ?? (session && pidIn("b_running") ? by("blocking.long_running_queries") : undefined)
      ?? (top.holder === "Prepared transaction" ? by("blocking.prepared_transactions") : undefined)
      ?? (top.holder === "Replication slot" ? by("replication.bad_slots") : undefined)
      ?? horizon;
  }
  // What is holding vacuum back, named the way someone would look for it.
  const who = !top ? "" : top.holder === "Backend session"
    ? (rows("b_idle").some((r) => String(r.pid) === String(top.ref)) ? `the session idle in a transaction (PID ${top.ref})` : rows("b_running").some((r) => String(r.pid) === String(top.ref)) ? `the query running as PID ${top.ref}` : `the transaction in PID ${top.ref}`)
    : top.holder === "Prepared transaction" ? `the prepared transaction ${top.ref}` : top.holder === "Replication slot" ? `the replication slot ${top.ref}` : `the standby ${top.ref}`;
  const effects = HOLDS_VACUUM.map(by).filter((f): f is Finding => Boolean(f));
  if (holder && effects.length) {
    holder.priority = "now";
    note(holder, `Fix this first. ${who.charAt(0).toUpperCase() + who.slice(1)} has held back cleanup for ${fmtN(num(top!.xmin_age))} transactions, so vacuum can't remove dead rows in any table${deadTables.length ? `, including ${list(deadTables)}` : ""}.`);
    if (horizon && horizon !== holder) { link(holder, horizon); note(horizon, `The oldest holder is ${who}.`); }
    for (const e of effects) {
      link(holder, e);
      note(e, /wraparound|freeze/.test(e.id)
        ? `VACUUM (FREEZE) can't move the oldest transaction ID forward until ${who} ends.`
        : `Caused at least in part by ${who}: VACUUM can't remove these rows until it ends. End it, then scan again.`);
    }
  }

  // 2. Advice to add an index is premature when the table is full of dead rows or its statistics are stale.
  const stale = by("tables.stale_statistics");
  const staleTables = tablesIn(stale);
  /** Why `t` shouldn't get an index yet, said about the table or about a query that reads it. */
  const reason = (t: string, query: boolean) => {
    const subject = query ? `This query reads ${t}.` : `${t}:`;
    if (deadTables.includes(t) && dead) {
      const blocked = Boolean(holder && dead.cause);
      return { cause: blocked ? holder! : dead, text: `${subject} ${deadPct.get(t) ?? "Many"}% of its rows are dead, and sequential scans read dead rows too. ${blocked ? `End ${who}` : `Vacuum ${t}`}, then measure again before adding an index.` };
    }
    if (staleTables.includes(t) && stale) return { cause: stale, text: `${subject} Its planner statistics are stale. Run ANALYZE ${t} and measure again before rewriting ${query ? "the query" : "queries"} or adding an index.` };
    return null;
  };
  const seq = by("tables.seq_scans");
  if (seq) for (const t of tablesIn(seq)) { const r = reason(t, false); if (r) { link(r.cause, seq); note(seq, r.text); break; } }
  for (const q of QUERY_FINDINGS.map(by)) {
    if (!q || !Array.isArray(q.evidence)) continue;
    const sql = q.evidence.map((r) => r.query);
    const t = [...deadTables, ...staleTables].find((x) => sql.some((s) => mentions(s, x)));
    const r = t ? reason(t, true) : null;
    if (r) { link(r.cause, q); note(q, r.text); }
  }

  // 3. Blocked queries: the blocker is often a session idle in a transaction or a long-running statement.
  const blocked = by("blocking.lock_waits");
  if (blocked) {
    const bl = rows("b_blocked");
    const idle = by("blocking.idle_in_transaction"), running = by("blocking.long_running_queries");
    const fromIdle = bl.find((r) => r.blocking_state === "idle in transaction");
    const fromRunning = bl.find((r) => rows("b_running").some((x) => String(x.pid) === String(r.blocking_pid)));
    if (fromIdle && idle) {
      link(idle, blocked);
      note(blocked, `The blocking session (PID ${fromIdle.blocking_pid}) is idle in a transaction. Ending that transaction releases the lock.`);
      note(idle, `It also holds a lock that ${bl.length === 1 ? "a query is" : `${bl.length} queries are`} waiting for.`);
    } else if (fromRunning && running) {
      link(running, blocked);
      note(blocked, `The blocking session (PID ${fromRunning.blocking_pid}) is a long-running query.`);
    }
  }

  // 4. Connections near the limit: say what is using them before anyone raises max_connections.
  const sat = by("connections.saturation");
  if (sat) {
    const c = rows("c_limits")[0];
    const idleConns = by("connections.idle_sessions");
    if (blocked) { link(blocked, sat); note(sat, "Queries waiting on locks keep their connections open, so fix the lock waits and check the count again."); }
    else if (idleConns) { link(idleConns, sat); note(sat, `${fmtN(num(c?.idle))} of the ${fmtN(num(c?.in_use))} connections are idle. A connection pooler lowers the count; raising max_connections adds memory for every connection.`); }
  }

  // 5. Before adding CPU or memory: is one query or table responsible?
  const culprit = by("queries.dominant") ?? seq ?? by("queries.slow_average");
  for (const c of CAPACITY.map(by)) {
    if (!c) continue;
    const ioCause = c.id === "capacity.io_wait" ? by("tables.bloat") ?? dead : undefined;
    const cause = ioCause ?? culprit;
    if (!cause) continue;
    link(cause, c);
    note(c, `Before adding CPU or memory: ${lc(cause.title)}. A larger instance would run the same plans, so fix that first and measure again.`);
  }
  const spillQ = by("queries.temp_spill");
  for (const id of ["capacity.temp_spill", "config.work_mem_spills"]) {
    const f = by(id);
    if (f && spillQ) { link(spillQ, f); note(f, "The statements writing the temp files are in the queries finding listed before this one. Raise work_mem only for the roles that run them: a global increase applies to every sort in every connection."); }
  }

  // 6. Too little history: usage-based findings can't be trusted yet.
  const reset = rows("l_db")[0]?.stats_reset;
  const uptime = vitals.find((v) => v.label === "Uptime")?.value;
  const windowS = reset ? (Date.now() - new Date(String(reset)).getTime()) / 1000 : typeof uptime === "number" ? uptime : null;
  const unused = by("indexes.unused");
  if (unused && windowS !== null && windowS < 7 * 86_400) {
    unused.priority = "ignore";
    note(unused, `Index usage counts cover only the last ${span(windowS)}. An index used by a weekly or monthly job would look unused, so check again after a full business cycle before dropping any.`);
  }

  // Order: priority, then severity, then a cause directly before what it causes.
  const out = fs.map((f) => ({ ...f, ...(notes.has(f.id) ? { note: notes.get(f.id)!.join(" ") } : {}) }))
    .sort((a, b) => rank(a.priority!) - rank(b.priority!) || SEV.indexOf(a.severity) - SEV.indexOf(b.severity));
  for (let pass = 0; pass < out.length; pass++) {
    let moved = false;
    for (let i = 0; i < out.length; i++) {
      const j = out[i].cause ? out.findIndex((f) => f.id === out[i].cause) : -1;
      if (j > i) { out.splice(i, 0, out.splice(j, 1)[0]); moved = true; break; }
    }
    if (!moved) break;
  }
  return out;
}
